function [Mv,Classv,duv,Mu,Classu]=MetamerismIndex(SPD,daylightsource)
%calculates the metamerism index
%spd = spectral power distribution
%daylightsource = 'D65', 'ID65' (indoor), 'D50','D55' or 'D75'
%Output:
%   Mv = visual M-index
%   Classv = visual class (A-E)
%   duv (should be < 0.015)
%   Mu = UV M-index
%   Classu = UV class (A-E)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


l0=300;ln=830;l0_=380;ln_=780;samplestep=5;lam=(l0:samplestep:ln)';l0uvQbetaF=300;l0uv=400;lnuv=700;

if abs(SPD(1,1)-SPD(1,2))==1 & SPD(1,1)<=l0 & SPD(end,1)>=ln;spd=SPD((SPD(1,1)-l0+1:samplestep:ln-SPD(1,1)+1)',2);lam=SPD((SPD(1,1)-l0+1:samplestep:ln-SPD(1,1)+1)',1),end%keep only 5nm datapoints
if abs(SPD(1,1)-SPD(1,2))==samplestep & SPD(1,1)<=l0 & SPD(end,1)>=ln;spd=SPD(((SPD(1,1)-l0)/samplestep+1:1:(ln-SPD(1,1))/samplestep+1)',2),lam_=SPD(((SPD(1,1)-l0)/samplestep+1:1:(ln-SPD(1,1))/samplestep+1)',1),end%adjust range
if abs(SPD(1,1)-SPD(1,2))~=samplestep | SPD(1,1)>=l0 | SPD(end,1)<ln;spd=neg2zero(interp1(SPD(:,1),SPD(:,2),(l0:samplestep:ln)','linear','extrap'));end%to account for non-1nm or 5nm spectral data


