MUVr=MUVr(abs(MUVr(1,1)-l0uv)./samplestep+1:abs(MUVr(1,1)-lnuv)./samplestep+1,2:end);
Rr=MUVr(:,[1,5,9]+t-1);

%normalize spd
wp_=(abs(l0-l0_)/samplestep+1:abs(l0-ln_)/samplestep+1)';
Snt=100.*spd./sum(cmf10(:,2).*spd*samplestep);%l0 to ln range
Snt_=100.*spd(wp_)./sum(cmf10(wp_,2).*spd(wp_)*samplestep);%l0_ to ln_ range
Snr=100.*spd2./sum(cmf10(:,2).*spd2*samplestep);%l0 to ln range
Snr_=100.*spd2(wp_)./sum(cmf10(wp_,2).*spd2(wp_)*samplestep);%l0_ to ln_ range


%Mv = from l0_ to ln_ (=380-780 nm)
XYZt=[sum(Snt_.*cmf10(wp_,1).*samplestep),sum(Snt_.*cmf10(wp_,2).*samplestep),sum(Snt_.*cmf10(wp_,3).*samplestep)];
XYZr=[sum(Snr_.*cmf10(wp_,1).*samplestep),sum(Snr_.*cmf10(wp_,2).*samplestep),sum(Snr_.*cmf10(wp_,3).*samplestep)];
uvt=xyz2uvp(XYZt);uvr=xyz2uvp(XYZr);duv=sqrt((uvt(1)-uvr(1)).^2+(uvt(2)-uvr(2)).^2);
if duv<=0.015;disp('Chromaticty of simulator passed! (duv <=0.015)');end

for i=1:size(Mvisstandard,2);
    XYZtiS(i,:)=[sum(Snt_.*Mvisstandard(:,i).*cmf10(wp_,1).*samplestep),sum(Snt_.*Mvisstandard(:,i).*cmf10(wp_,2).*samplestep),sum(Snt_.*Mvisstandard(:,i).*cmf10(wp_,3).*samplestep)];
    XYZtiR(i,:)=[sum(Snt_.*Mvisref(:,i).*cmf10(wp_,1).*samplestep),sum(Snt_.*Mvisref(:,i).*cmf10(wp_,2).*samplestep),sum(Snt_.*Mvisref(:,i).*cmf10(wp_,3).*samplestep)];
    XYZriS(i,:)=[sum(Snr_.*Mvisstandard(:,i).*cmf10(wp_,1).*samplestep),sum(Snr_.*Mvisstandard(:,i).*cmf10(wp_,2).*samplestep),sum(Snr_.*Mvisstandard(:,i).*cmf10(wp_,3).*samplestep)];
    XYZriR(i,:)=[sum(Snr_.*Mvisref(:,i).*cmf10(wp_,1).*samplestep),sum(Snr_.*Mvisref(:,i).*cmf10(wp_,2).*samplestep),sum(Snr_.*Mvisref(:,i).*cmf10(wp_,3).*samplestep)];
end

labtS=xyz2lab(XYZtiS,XYZt);labtR=xyz2lab(XYZtiR,XYZt);labrS=xyz2lab(XYZriS,XYZr);labrR=xyz2lab(XYZriR,XYZr);
dEabt=sqrt((labtS(:,1)-labtR(:,1)).^2+(labtS(:,2)-labtR(:,2)).^2+(labtS(:,3)-labtR(:,3)).^2);
dEabr=sqrt((labrS(:,1)-labrR(:,1)).^2+(labrS(:,2)-labrR(:,2)).^2+(labrS(:,3)-labrR(:,3)).^2);
Mv=mean(dEabt);Mvr=mean(dEabr);
if Mv>2;Classv='E';end
if Mv<=2;Classv='D';end
if Mv<=1;Classv='C';end
if Mv<=0.5;Classv='B';end
if Mv<=0.25;Classv='A';end
    
if l0==300;
%Mu = mixed range
clear XYZtiS XYZtiR XYZriS XYZriR labtS labrS labtR labrR dEabt dEabr
wpQuvbetaF=(abs(l0-l0uvQbetaF)/samplestep+1:abs(l0-lnuv)/samplestep+1)';%300 to 700 nm, count starting from 300 (=l0)
wp=(abs(l0-l0uv)/samplestep+1:abs(l0-lnuv)/samplestep+1)';%400 to 700 nm , count starting from 300  (=l0)
for i=1:size(Q,2)
    %%standard uv samples
    %l0 to lnuv range (300-700nm)
    Nt=sum(Snt(wpQuvbetaF).*Q(:,i));Nr=sum(Snr(wpQuvbetaF).*Q(:,i));
    betaLxSnt=(Nt.*F(:,i));betaLxSnr=(Nr.*F(:,i));%don't divide by Sn HERE to avoid division by zero
    betaTxSnt=betaS(:,i).*Snt(wpQuvbetaF)+betaLxSnt;betaTxSnr=betaS(:,i).*Snr(wpQuvbetaF)+betaLxSnr;
    
    %l0uv to lnuv range (400-700 nm)
    XYZtiS(i,:)=[sum(betaTxSnt(wp).*cmf10(wp,1).*samplestep),sum(betaTxSnt(wp).*cmf10(wp,2).*samplestep),sum(betaTxSnt(wp).*cmf10(wp,3).*samplestep)];
    XYZriS(i,:)=[sum(betaTxSnr(wp).*cmf10(wp,1).*samplestep),sum(betaTxSnr(wp).*cmf10(wp,2).*samplestep),sum(betaTxSnr(wp).*cmf10(wp,3).*samplestep)];
    XYZtiR(i,:)=[sum(Snt(wp).*Rr(:,i).*cmf10(wp,1).*samplestep),sum(Snt(wp).*Rr(:,i).*cmf10(wp,2).*samplestep),sum(Snt(wp).*Rr(:,i).*cmf10(wp,3).*samplestep)];
    XYZriR(i,:)=[sum(Snr(wp).*Rr(:,i).*cmf10(wp,1).*samplestep),sum(Snr(wp).*Rr(:,i).*cmf10(wp,2).*samplestep),sum(Snr(wp).*Rr(:,i).*cmf10(wp,3).*samplestep)];
end

labtS=xyz2lab(XYZtiS,XYZt);labtR=xyz2lab(XYZtiR,XYZt);labrS=xyz2lab(XYZriS,XYZr);labrR=xyz2lab(XYZriR,XYZr);
dEabt=sqrt((labtS(:,1)-labtR(:,1)).^2+(labtS(:,2)-labtR(:,2)).^2+(labtS(:,3)-labtR(:,3)).^2);
dEabr=sqrt((labrS(:,1)-labrR(:,1)).^2+(labrS(:,2)-labrR(:,2)).^2+(labrS(:,3)-labrR(:,3)).^2);
Mu=mean(dEabt);Mur=mean(dEabr);

if Mu>2;Classu='E';end
if Mu<=2;Classu='D';end
if Mu<=1;Classu='C';end
if Mu<=0.5;Classu='B';end
if Mu<=0.25;Classu='A';end

else
    Mu=100;Classu='?';
end
    
end

